choose.otherwise:
p.ship_line_id in (select sl.ship_line_id from wms_ship_line sl join wms_ship sh on sh.ship_id = sl.ship_id
                    where sh.plant_cd = #{plantCd}
     and sh.ship_no = #{shipNo}
     and sh.cust_id in (select cu.cust_id from mst_cust cu where cu.cust_cd = #{custCd})
     and sh.shipped_at >= #{fromAt}
     and sh.shipped_at < #{toAt})
 and p.lot_id in (select lo.lot_id from lot_master lo where lo.lot_no = #{lotNo})

mapper.select:
select  
 where r.plant_cd = #{plantCd}
 and r.status = #{status}
 and r.received_at >= #{fromAt}
 and r.received_at < #{toAt}
 order by r.received_at desc, r.rtn_id desc
 limit #{limit}
